    csv_update: 'ஒரே குறியீடு உள்ள பழைய பொருட்களைப் புதுப்பி', import_done: 'இறக்குமதி: {added} புதியவை, {updated} புதுப்பிப்பு, {skipped} தவிர்க்கப்பட்டவை.', import_bad: 'இந்தக் கோப்பைப் பொருட்கள் CSV ஆகப் படிக்க முடியவில்லை.', import_note: 'CSV இறக்குமதி',
    backup_title: 'பேக்அப் மற்றும் மீட்டெடுப்பு', backup_help: 'பேக்அப் என்பது எல்லாப் பொருட்கள், வரவு-விடுவிப்புகள் மற்றும் அமைப்புகளைக் கொண்ட ஒரு JSON கோப்பு. இதை Google Drive, WhatsApp அல்லது பென் டிரைவில் வைக்கவும். மீட்டெடுத்தால் தற்போதைய தரவு மாற்றப்படும்.',
    backup_dl: 'பேக்அப் பதிவிறக்கு', restore: 'பேக்அப்பிலிருந்து மீட்டெடு', last_backup: 'கடைசி பேக்அப்: {date}', never_backup: 'இன்னும் பேக்அப் எடுக்கவில்லை.',
    remind_txt: 'கடைசி பேக்அப்பிற்கு {n} நாட்கள் ஆகிவிட்டன. இப்போதே பதிவிறக்கவும்; ஒரு விநாடிதான்.', remind_never: 'நீங்கள் இன்னும் பேக்அப் எடுக்கவில்லை. இப்போதே பதிவிறக்கவும்; ஒரு விநாடிதான்.', backup_now: 'இப்போதே பேக்அப்', later: 'பிறகு',
    restore_bad: 'இது ஸ்டாக் பதிவேட்டின் பேக்அப் கோப்பு அல்ல.', confirm_restore: 'தற்போதைய எல்லாத் தரவையும் இந்தப் பேக்அப்பால் மாற்றவா?', restore_ok: '{items} பொருட்கள் மற்றும் {moves} பதிவுகள் மீட்டெடுக்கப்பட்டன.',
    storage_title: 'இந்த சாதனத்தில் சேமிப்பகம்', storage_used: 'பயன்பாடு: சுமார் 5,000 KB இல் {kb} KB', persist_yes: 'இந்தத் தரவை வைத்திருக்க உலாவி உறுதியளித்துள்ளது.', persist_no: 'இடம் குறைந்தால் உலாவி இந்தத் தரவை அழிக்கலாம். பேக்அப் வைத்திருங்கள்.', persist_unknown: 'வழக்கமாகப் பேக்அப் எடுங்கள்; உலாவிகள் தளத் தரவை அழிக்கலாம்.',
    quota_warn: 'சேமிப்பகம் கிட்டத்தட்ட நிரம்பிவிட்டது (சுமார் 5,000 KB இல் {kb} KB). பேக்அப் பதிவிறக்கி, பழைய பதிவுகளை நீக்கவும்.', store_full: 'சேமிக்க முடியவில்லை: சேமிப்பகம் நிரம்பியது அல்லது தடுக்கப்பட்டது. இப்போதே பேக்அப் பதிவிறக்கவும்.',
    danger_title: 'ஆபத்துப் பகுதி', clear_old: 'இந்தத் தேதிக்கு முந்தைய பதிவுகளை நீக்கு (ஸ்டாக் மாறாது)', clear_old_btn: 'பழைய பதிவுகளை நீக்கு', confirm_clear_old: '{date} க்கு முந்தைய {n} பதிவுகளை நீக்கவா? தற்போதைய ஸ்டாக் மாறாது.', cleared_old: '{n} பழைய பதிவுகள் நீக்கப்பட்டன.', none_old: 'அந்தத் தேதிக்கு முன் பதிவுகள் இல்லை.', reset_all: 'எல்லாவற்றையும் நீக்கு',
    sheet_title: 'ஸ்டாக் எண்ணிக்கைத் தாள்', sheet_date: 'தேதி', sheet_by: 'எண்ணியவர்', sheet_no: 'எண்', sheet_book: 'பதிவேட்டு ஸ்டாக்', sheet_counted: 'எண்ணியது', sheet_diff: 'வேறுபாடு', sheet_remarks: 'குறிப்புகள்', sheet_sign: 'கையொப்பம்', sheet_footer: 'ஒவ்வொரு வேறுபாட்டையும் ஸ்டாக் பதிவேட்டில் சரிசெய்தலாகப் பதிவு செய்யவும்.',
    tip1: 'ஒவ்வொரு பொருளையும் ஒருமுறை சேர்க்கவும்: பார்கோடு, அலகு, விலைகள், குறைந்தபட்ச ஸ்டாக். எண்ணிக்கையைப் பதிவேடு பார்த்துக்கொள்ளும்.',
    tip2: 'ஸ்கேனர் பெட்டியில் கிளிக் செய்து, "சரக்கு விடுவிப்பு −1" ஐத் தேர்ந்தெடுத்து, விற்கும்போது பொருட்களை ஸ்கேன் செய்யவும்; ஒவ்வொரு ஸ்கேனும் ஸ்டாக்கை ஒன்று குறைக்கும். பெரிய அளவுக்கு வரவு / விடுவிப்பு பொத்தான்களைப் பயன்படுத்தவும்.',
    tip3: '"குறைந்த ஸ்டாக்" டைல் சப்ளையரிடம் என்ன ஆர்டர் செய்ய வேண்டும் என்று காட்டும். பொருட்கள் CSV ஐ ஏற்றுமதி செய்து WhatsApp இல் அனுப்பவும்.',
    tip4: 'மருந்து, பால், அழகுசாதனக் கடைகள்: காலாவதி தேதிகளைச் சேர்த்து, வாரம் ஒருமுறை காலாவதிப் பிரிவைப் பார்க்கவும்.',
    tip5: 'ஸ்டாக் எண்ணிக்கைத் தாளை அச்சிட்டு, கிடங்கை எண்ணி, வேறுபாடுகளைச் சரிசெய்தலாகப் பதிவு செய்யவும்.',
    tip6: 'வாரம் ஒருமுறை பேக்அப் பதிவிறக்கி Google Drive அல்லது பென் டிரைவில் வைக்கவும். உலாவிகள் தரவை அழிக்கலாம்.',
